class Solution {
    public boolean wordBreak(String s, List<String> wordDict) {
        return canSegmentFrom(s, wordDict, 0);
    }

    private boolean canSegmentFrom(String s, List<String> wordDict, int start) {
        if (start == s.length()) return true;
        for (String word : wordDict) {
            if (s.startsWith(word, start)
                    && canSegmentFrom(s, wordDict, start + word.length())) {
                return true;
            }
        }
        return false;
    }
}

